item.command:
/bin/bash -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#f8f9f5">
  <meta name="description" content="Plan your home clean in four simple steps.">
  <title>Book a clean · Tidy</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      color-scheme: light;
      --bg:#f8f9f5; --surface:#fff; --text:#253e32; --muted:#647166; --accent:#315e43; --accent-hover:#244a34; --tint:#edf2e7; --tint-strong:#dce7cf; --border:#e0e5db; --control:#849082; --placeholder:#727d74; --danger:#a63232; --danger-bg:#fff5f3; --white:#fff;
      --font:'"'DM Sans',sans-serif; --s1:4px; --s2:8px; --s3:12px; --s4:16px; --s5:24px; --s6:32px; --s7:48px; --s8:64px;
      --radius:8px; --radius-lg:16px; --ease:cubic-bezier(.2,.7,.3,1);
    }
    * {box-sizing:border-box}
    body {margin:0;background:var(--bg);color:var(--text);font:16px/1.5 var(--font);-webkit-font-smoothing:antialiased}
    button,input,textarea {font:inherit}
    button {cursor:pointer;color:inherit;touch-action:manipulation}
    button,input,textarea {transition:background .16s var(--ease),border-color .16s var(--ease),box-shadow .16s var(--ease)}
    button:focus-visible,input:focus-visible,textarea:focus-visible,a:focus-visible {outline:3px solid var(--accent);outline-offset:4px}
    button:disabled {cursor:default;opacity:.4}
    button:active:not(:disabled) {transform:translateY(1px)}
    h1,h2,h3,p {margin:0}
    h1,h2,h3 {text-wrap:balance}
    svg {width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}
    .sprite {display:none}
    .shell {width:min(1088px,calc(100% - 64px));margin:auto}
    .site-header {height:96px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between}
    .brand {display:flex;align-items:center;gap:8px;font-size:32px;font-weight:700;letter-spacing:-1.6px;line-height:1}
    .brand svg {width:36px;height:36px;stroke-width:2}
    .header-note {font-size:14px;color:var(--muted);display:flex;align-items:center;gap:8px}
    .header-note svg {width:18px;height:18px}
    main {padding:48px 0 32px}
    .intro {display:flex;align-items:center;justify-content:space-between;margin-bottom:32px}
    h1 {font-size:40px;line-height:1.2;letter-spacing:-1.6px;font-weight:600;margin-bottom:12px}
    .intro p {color:var(--muted)}
    .home-drawing {width:152px;height:96px;stroke:var(--accent);stroke-width:1.5;margin-right:24px}
    .steps {list-style:none;display:grid;grid-template-columns:repeat(4,1fr);padding:0;margin:0 0 32px;gap:16px}
    .step {position:relative}
    .step::after {content:'';position:absolute;height:1px;background:var(--border);top:20px;left:52px;right:4px}
    .step:last-child::after {display:none}
    .step-button {display:flex;align-items:center;gap:12px;border:0;background:none;padding:0;min-height:44px;font-size:14px;font-weight:500;width:100%;text-align:left}
    .step-button:disabled {opacity:1;cursor:default}
    .step-num {display:grid;place-items:center;flex-shrink:0;width:40px;height:40px;border-radius:50%;border:1px solid var(--control);background:var(--bg);color:var(--muted);z-index:1;font-size:14px;position:relative}
    .step-label {position:relative;z-index:1;background:var(--bg);padding-right:12px;color:var(--muted)}
    .step.current .step-num {background:var(--accent);border-color:var(--accent);color:var(--white);box-shadow:0 0 0 4px var(--tint-strong)}
    .step.current .step-label {color:var(--text);font-weight:700}
    .step.complete .step-num {background:var(--tint-strong);border-color:var(--tint-strong);color:var(--accent)}
    .step.complete .step-num svg {width:18px;height:18px}
    .layout {display:grid;grid-template-columns:minmax(0,704px) minmax(0,320px);align-items:start;gap:32px}
    .form-card {background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-lg);overflow:hidden;min-width:0}
    .panel {padding:32px}
    [hidden] {display:none"'!important}
    .panel-header {margin-bottom:32px}
    .step-caption {font-size:12px;letter-spacing:1.4px;text-transform:uppercase;color:var(--muted);font-weight:600;margin-bottom:8px}
    h2 {font-size:26px;font-weight:600;line-height:1.25;letter-spacing:-.7px;margin-bottom:8px}
    .panel-header p:last-child {font-size:14px;color:var(--muted)}
    .fields {display:grid;grid-template-columns:1fr 1fr;gap:24px 16px}
    .field {min-width:0}
    .full {grid-column:1/-1}
    label,.field-label,legend {display:block;font-size:14px;font-weight:500;margin-bottom:8px}
    label .optional {font-weight:400;color:var(--muted);font-size:12px;margin-left:4px}
    input:not([type=radio]),textarea {display:block;width:100%;height:52px;padding:12px 16px;background:var(--surface);border:1px solid var(--control);border-radius:var(--radius);color:var(--text);font-size:16px}
    input::placeholder,textarea::placeholder {color:var(--placeholder);font-weight:400}
    input:hover,textarea:hover {border-color:var(--accent)}
    input[aria-invalid=true],textarea[aria-invalid=true] {border-color:var(--danger);background:var(--danger-bg)}
    textarea {height:88px;resize:vertical}
    .error {font-size:12px;color:var(--danger);margin-top:8px}
    .error:empty {display:none}
    .field-hint {font-size:12px;color:var(--muted);margin-top:8px}
    .contact-note {display:flex;align-items:flex-start;gap:8px;font-size:12px;color:var(--muted);margin-top:24px}
    .contact-note svg {width:16px;height:16px;margin-top:1px}
    .actions {padding:24px 32px;border-top:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;gap:16px;background:var(--surface)}
    .action-note {font-size:12px;color:var(--muted)}
    .btn {border:0;min-height:48px;border-radius:var(--radius);padding:12px 24px;display:inline-flex;align-items:center;justify-content:center;gap:12px;font-size:14px;font-weight:600;text-decoration:none}
    .btn-primary {color:var(--white);background:var(--accent);min-width:172px}
    .btn-primary:hover {background:var(--accent-hover)}
    .btn svg {width:18px;height:18px}
    .btn-back {padding:12px 0;background:none;color:var(--muted)}
    .btn-back:hover {color:var(--text)}
    .summary {background:var(--tint);border-radius:var(--radius-lg);padding:24px}
    .summary-heading {display:flex;gap:12px;align-items:center;padding-bottom:24px;border-bottom:1px solid color-mix(in srgb,var(--accent) 17%,transparent)}
    .summary-heading>svg {width:32px;height:32px;stroke-width:1.4}
    .summary-heading h2 {font-size:18px;letter-spacing:-.4px;margin:0 0 4px}
    .summary-heading p {font-size:12px;color:var(--muted)}
    .summary-row {display:flex;align-items:flex-start;gap:12px;padding-top:24px}
    .summary-row>svg {width:20px;height:20px;color:var(--muted);margin-top:2px}
    .summary-row .label {font-size:12px;color:var(--muted);margin-bottom:4px}
    .summary-row .value {font-size:14px;overflow-wrap:anywhere}
    .summary-row .empty {color:var(--muted)}
    .summary-row .small {font-size:12px;color:var(--muted);margin-top:4px;overflow-wrap:anywhere}
    .summary-footer {border-top:1px solid color-mix(in srgb,var(--accent) 17%,transparent);padding-top:20px;margin-top:24px;font-size:12px;color:var(--muted);display:flex;gap:8px;align-items:flex-start}
    .summary-footer svg {width:16px;height:16px;margin-top:1px}
    .preview-note {font-size:12px;color:var(--muted);margin:16px 12px;line-height:1.6}
    footer {display:flex;justify-content:space-between;gap:16px;padding-top:32px;font-size:12px;color:var(--muted)}
    .footer-brand {font-weight:600;letter-spacing:-.3px}
    fieldset {border:0;padding:0;margin:0;min-width:0}
    .choices {display:grid;grid-template-columns:repeat(6,1fr);gap:8px}
    .choices.two {grid-template-columns:1fr 1fr}
    .choice {position:relative;margin:0;cursor:pointer}
    .choice input {position:absolute;opacity:0;width:1px;height:1px}
    .choice span {display:flex;align-items:center;justify-content:center;min-height:48px;border:1px solid var(--control);border-radius:var(--radius);font-size:14px;gap:8px;background:var(--surface)}
    .choice:hover span {border-color:var(--accent);background:var(--tint)}
    .choice input:checked+span {border:2px solid var(--accent);background:var(--tint);color:var(--accent);font-weight:600}
    .choice input:focus-visible+span {outline:3px solid var(--accent);outline-offset:3px}
    .choice input[aria-invalid=true]+span {border-color:var(--danger)}
    .section-divider {height:1px;background:var(--border);margin:24px 0}
    .calendar {border:1px solid var(--border);border-radius:var(--radius);padding:16px;margin-top:8px}
    .calendar-header {display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
    .calendar-header h3 {font-size:16px;font-weight:600}
    .icon-button {width:44px;height:44px;border:0;border-radius:var(--radius);display:grid;place-items:center;background:transparent}
    .icon-button:hover:not(:disabled) {background:var(--tint)}
    .icon-button svg {width:20px;height:20px}
    .calendar-grid {display:grid;grid-template-columns:repeat(7,1fr);gap:4px}
    .weekday {font-size:12px;text-align:center;padding:8px 0;color:var(--muted)}
    .day {min-height:44px;border:1px solid transparent;background:none;border-radius:var(--radius);font-size:14px;font-variant-numeric:tabular-nums}
    .day:hover:not(:disabled) {background:var(--tint);border-color:var(--accent)}
    .day[aria-pressed=true] {background:var(--accent);color:var(--white)}
    .day.today {border-color:var(--control)}
    .slot-field {margin-top:24px}
    .time-choices {grid-template-columns:1fr 1fr}
    .time-choices .choice span {flex-direction:column;gap:0;padding:12px}
    .time-choices small {font-size:12px;font-weight:400;color:var(--muted)}
    .schedule-note {font-size:12px;color:var(--muted);margin-top:16px}
    .review-block+.review-block {border-top:1px solid var(--border);padding-top:24px;margin-top:24px}
    .review-top {display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:8px}
    .review-top h3 {font-size:14px;font-weight:600}
    .edit {border:0;background:none;color:var(--accent);font-size:12px;font-weight:600;min-height:44px;padding:8px;display:flex;align-items:center;gap:4px;margin:-8px}
    .edit:hover {text-decoration:underline}
    .edit svg {width:14px;height:14px}
    .review-content {font-size:14px;color:var(--muted);line-height:1.7;overflow-wrap:anywhere;white-space:pre-line}
    .review-info {background:var(--tint);padding:16px;border-radius:var(--radius);font-size:12px;margin-top:24px;color:var(--muted)}
    .success {padding:48px 32px}
    .success-mark {display:grid;place-items:center;width:64px;height:64px;background:var(--tint-strong);border-radius:50%;color:var(--accent);margin-bottom:24px}
    .success-mark svg {width:32px;height:32px}
    .success>p {color:var(--muted);font-size:14px;margin-top:16px;max-width:42ch}
    .success-detail {border-top:1px solid var(--border);border-bottom:1px solid var(--border);margin-top:24px;padding:24px 0;font-size:14px;white-space:pre-line;overflow-wrap:anywhere}
    .success .btn {margin-top:24px}
    @media(min-width:769px) {.panel {min-height:428px}}
    @media(max-width:900px) {.shell {width:calc(100% - 48px)}.layout {grid-template-columns:minmax(0,1fr) 280px;gap:24px}.panel,.actions {padding:24px}.step-button {gap:8px}.step-label {padding-right:4px}.step::after {left:48px}.summary {padding:24px 20px}h1 {font-size:36px}}
    @media(max-width:768px) {
      .shell {width:calc(100% - 40px)}.site-header {height:80px}.brand {font-size:28px}.brand svg {width:32px;height:32px}
      main {padding-top:32px}.intro {margin-bottom:24px}.intro p {font-size:14px}h1 {font-size:32px;letter-spacing:-1.2px;margin-bottom:8px}.home-drawing {width:104px;height:80px;margin-right:0}
      .layout {grid-template-columns:1fr;gap:24px}.steps {gap:8px;margin-bottom:24px}.step-button {flex-direction:column;align-items:flex-start;gap:12px;font-size:12px}.step::after {top:18px;left:48px;right:4px}.step-num {width:36px;height:36px;font-size:12px}.step-label {padding:0}.step.current .step-label {font-weight:600}
      .panel-header {margin-bottom:24px}h2 {font-size:24px}.summary {padding:24px}.summary-heading {padding-bottom:16px}.summary-row {padding-top:16px}.summary-footer {margin-top:24px}.preview-note {margin-bottom:0}
      .actions {position:sticky;bottom:0;z-index:3;box-shadow:0 -8px 16px color-mix(in srgb,var(--text) 3%,transparent);padding-bottom:max(16px,env(safe-area-inset-bottom));padding-top:16px}.form-card {overflow:visible}.panel {border-radius:var(--radius-lg)}
      .action-note {max-width:105px}.btn-primary {min-width:168px}footer {padding-top:24px;padding-bottom:8px}.form-card {border-bottom-left-radius:var(--radius-lg)}
    }
    @media(max-width:420px) {.shell {width:calc(100% - 32px)}.header-note {font-size:12px}.header-note svg {display:none}.home-drawing {display:none}.panel {padding:24px 20px}.actions {padding-left:20px;padding-right:20px}.fields {gap:20px 12px}.fields .contact-field {grid-column:1/-1}.choices {gap:4px}.choice span {font-size:13px}.calendar {padding:12px 8px}.calendar-grid {gap:0}.day {min-height:44px}.btn {padding-left:16px;padding-right:16px}footer {font-size:11px}.step-label {font-size:11px}}
    @media(prefers-reduced-motion:reduce) {*,*::before,*::after {scroll-behavior:auto!important;transition:none!important;animation:none!important}}
    @media(prefers-color-scheme:dark) {:root {color-scheme:dark;--bg:#17221c;--surface:#1e2c24;--text:#edf3e8;--muted:#b4bfb1;--accent:#b5d3a1;--accent-hover:#cbe2bd;--tint:#28382b;--tint-strong:#354c34;--border:#3d4b40;--control:#859681;--placeholder:#a8b5a5;--danger:#ffb4ac;--danger-bg:#412b29;--white:#17251c}.brand {color:var(--accent)}}
  </style>
</head>
<body>
  <svg class="sprite" xmlns="http://www.w3.org/2000/svg"><defs>
    <symbol id="i-home" viewBox="0 0 24 24"><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z"/><path d="M9 21v-8h6v8"/></symbol>
    <symbol id="i-arrow" viewBox="0 0 24 24"><path d="M4 12h16m-6-6 6 6-6 6"/></symbol>
    <symbol id="i-back" viewBox="0 0 24 24"><path d="M20 12H4m6-6-6 6 6 6"/></symbol>
    <symbol id="i-check" viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></symbol>
    <symbol id="i-calendar" viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/></symbol>
    <symbol id="i-pin" viewBox="0 0 24 24"><path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/></symbol>
    <symbol id="i-user" viewBox="0 0 24 24"><circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></symbol>
    <symbol id="i-info" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/></symbol>
    <symbol id="i-sparkle" viewBox="0 0 24 24"><path d="m12 3 2.2 6.8L21 12l-6.8 2.2L12 21l-2.2-6.8L3 12l6.8-2.2ZM20 2v4m-2-2h4"/></symbol>
    <symbol id="i-edit" viewBox="0 0 24 24"><path d="m16 3 5 5L8 21H3v-5Zm-2 2 5 5"/></symbol>
  </defs></svg>
  <div class="shell">
    <header class="site-header">
      <div class="brand" aria-label="Tidy"><svg viewBox="0 0 36 36" aria-hidden="true"><path d="m5 17 13-11 13 11M8 15v16h20V15M15 31V21h6v10"/><path d="M28 3v6m-3-3h6"/></svg>tidy.</div>
      <div class="header-note"><svg aria-hidden="true"><use href="#i-sparkle"/></svg> Home cleaning, your way</div>
    </header>
    <main>
      <div class="intro">
        <div><h1>Book your home clean.</h1><p>A few details to make it feel like home again.</p></div>
        <svg class="home-drawing" viewBox="0 0 152 96" aria-hidden="true"><path d="M8 85h137M29 85V39l36-27 36 27v46M23 43l42-32 42 32M44 85V60h22v25M79 46h10v13H79zM41 37h12v12H41z"/><path d="M117 85V52m0 12c-14 0-15-13-15-13s15-2 15 13Zm0-6c14 0 15-14 15-14s-15 0-15 14Zm-8 17h17l-2 10h-13Z" fill="var(--tint-strong)"/><path d="m129 16 2 7 7 2-7 2-2 7-2-7-7-2 7-2ZM15 50v8m-4-4h8"/></svg>
      </div>
      <nav aria-label="Booking progress"><ol class="steps">
        <li class="step current"><button class="step-button" type="button" data-step="0" aria-current="step"><span class="step-num">1</span><span class="step-label">Contact details</span></button></li>
        <li class="step"><button class="step-button" type="button" data-step="1" disabled><span class="step-num">2</span><span class="step-label">Your home</span></button></li>
        <li class="step"><button class="step-button" type="button" data-step="2" disabled><span class="step-num">3</span><span class="step-label">Date & time</span></button></li>
        <li class="step"><button class="step-button" type="button" data-step="3" disabled><span class="step-num">4</span><span class="step-label">Review</span></button></li>
      </ol></nav>
      <div class="layout">
        <form class="form-card" id="booking-form" novalidate>
          <section class="panel" data-panel="0" aria-labelledby="contact-heading">
            <div class="panel-header"><p class="step-caption">Step 1 of 4</p><h2 id="contact-heading" tabindex="-1">First, a little about you.</h2><p>Who are we making a little more room for?</p></div>
            <div class="fields">
              <div class="field contact-field"><label for="first-name">First name</label><input id="first-name" name="firstName" autocomplete="given-name" placeholder="First name" required maxlength="100" aria-describedby="first-name-error"><p class="error" id="first-name-error"></p></div>
              <div class="field contact-field"><label for="last-name">Last name</label><input id="last-name" name="lastName" autocomplete="family-name" placeholder="Last name" required maxlength="100" aria-describedby="last-name-error"><p class="error" id="last-name-error"></p></div>
              <div class="field full"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="254" aria-describedby="email-error"><p class="error" id="email-error"></p></div>
              <div class="field full"><label for="phone">Phone number</label><input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="Your phone number" required maxlength="30" aria-describedby="phone-error"><p class="error" id="phone-error"></p></div>
            </div>
            <p class="contact-note"><svg aria-hidden="true"><use href="#i-info"/></svg>Your contact details will appear in your booking review.</p>
          </section>
          <section class="panel" data-panel="1" aria-labelledby="home-heading" hidden>
            <div class="panel-header"><p class="step-caption">Step 2 of 4</p><h2 id="home-heading" tabindex="-1">Tell us about your home.</h2><p>A little context for a clean that fits your space.</p></div>
            <div class="fields">
              <div class="field full"><label for="address">Street address</label><input id="address" name="address" autocomplete="address-line1" placeholder="Street and house number" required maxlength="200" aria-describedby="address-error"><p class="error" id="address-error"></p></div>
              <div class="field full"><label for="apartment">Apartment or unit <span class="optional">Optional</span></label><input id="apartment" name="apartment" autocomplete="address-line2" placeholder="Apartment, unit, floor" maxlength="100"></div>
              <div class="field"><label for="city">City</label><input id="city" name="city" autocomplete="address-level2" required maxlength="100" aria-describedby="city-error"><p class="error" id="city-error"></p></div>
              <div class="field"><label for="postcode">Postal code</label><input id="postcode" name="postcode" autocomplete="postal-code" required maxlength="20" aria-describedby="postcode-error"><p class="error" id="postcode-error"></p></div>
              <fieldset class="full" id="bedrooms-field"><legend>Bedrooms</legend><div class="choices" id="bedroom-choices"></div><p class="error" id="bedrooms-error"></p></fieldset>
              <fieldset class="full" id="bathrooms-field"><legend>Bathrooms</legend><div class="choices" id="bathroom-choices"></div><p class="error" id="bathrooms-error"></p></fieldset>
              <fieldset class="full" id="pets-field"><legend>Any pets at home?</legend><div class="choices two"><label class="choice"><input type="radio" name="pets" value="No pets" required aria-describedby="pets-error"><span>No pets</span></label><label class="choice"><input type="radio" name="pets" value="Pets at home" required aria-describedby="pets-error"><span>Yes, I have pets</span></label></div><p class="error" id="pets-error"></p></fieldset>
              <div class="field full" id="pet-details-field" hidden><label for="pet-details">Tell us about your pets <span class="optional">Optional</span></label><input id="pet-details" name="petDetails" placeholder="For example, one friendly dog" maxlength="250"></div>
            </div>
          </section>
          <section class="panel" data-panel="2" aria-labelledby="schedule-heading" hidden>
            <div class="panel-header"><p class="step-caption">Step 3 of 4</p><h2 id="schedule-heading" tabindex="-1">Find your fresh start.</h2><p>Choose your preferred date and arrival window.</p></div>
            <span class="field-label" id="date-label">Cleaning date</span>
            <div class="calendar" role="group" aria-labelledby="date-label" aria-describedby="date-error">
